	.print-format td, .print-format div, .print-format p {
		font-family: Tahoma, sans-serif;
		line-height: 150%;
		vertical-align: middle;
	}
	@media screen {
		.print-format {
			width: 4in;
			padding: 0.25in;
			min-height: 8in;
		}
	}
